// Throwaway analysis tool for slice-3 architecture memo. Not part of the deliverable.
use std::collections::BTreeMap;
use std::path::PathBuf;

use prism::call_graph::CallGraph;
use prism::navigation::NavigationIndex;
use prism::resolution::{DropReason, ResolutionConfidence, ResolutionKind};

fn dir_of(path: &str) -> &str {
    match path.rfind('/') {
        Some(i) => &path[..i],
        None => "",
    }
}

fn file_stem(path: &str) -> &str {
    let base = match path.rfind('/') {
        Some(i) => &path[i + 1..],
        None => path,
    };
    match base.rfind('.') {
        Some(i) => &base[..i],
        None => base,
    }
}

fn main() {
    let repo_path = std::env::args().nth(1).expect("repo path");
    let repo = std::sync::Arc::new(prism::repo_loader::load_repo(&PathBuf::from(&repo_path)).unwrap());
    let index = NavigationIndex::build(&repo);
    let cg: &CallGraph = &index.cpg.call_graph;

    let mut total_free_multi = 0usize;
    let mut same_dir_singleton = 0usize;
    let mut same_dir_multi = 0usize;
    let mut same_dir_zero_has_import_hit = 0usize;
    let mut same_dir_zero_import_hit_singleton = 0usize;
    let mut same_dir_zero_import_hit_multi = 0usize;
    let mut same_dir_zero_no_import = 0usize;
    let mut same_dir_zero_no_import_examples: Vec<String> = Vec::new();
    let mut same_dir_multi_examples: Vec<String> = Vec::new();

    for sites in cg.calls.values() {
        for site in sites {
            let out = cg.resolve_call_site_full(site);
            let is_free_multi = out.resolved.iter().any(|c| {
                c.kind == ResolutionKind::FreeMulti && c.confidence == ResolutionConfidence::NameOnly
            }) || out.drop == Some(DropReason::MultiOwnerCollision) && false;
            if !is_free_multi {
                continue;
            }
            // only count once per site (site-level), not per fanned-out callee
            total_free_multi += 1;

            let name = &site.callee_name;
            let caller_file = &site.caller.file;
            let caller_dir = dir_of(caller_file);

            let ids = match cg.functions.get(name) {
                Some(v) => v,
                None => continue,
            };
            let free: Vec<_> = ids
                .iter()
                .filter(|fid| !cg.method_owners.contains_key(*fid))
                .collect();

            let same_dir: Vec<_> = free.iter().filter(|f| dir_of(&f.file) == caller_dir).collect();

            match same_dir.len() {
                1 => same_dir_singleton += 1,
                0 => {
                    // no candidate in caller's own directory -- would same-dir
                    // preference even fire? check import-qualified narrowing
                    // instead: does caller's file import `name` from some module,
                    // and does that module resolve to a unique file?
                    let mut import_hit = false;
                    if let Some(file_imports) = cg.imports.get(caller_file) {
                        if let Some(module_path) = file_imports.get(name) {
                            let module_last =
                                module_path.rsplit('/').next().unwrap_or(module_path);
                            let module_stem =
                                module_last.rsplit('.').last().unwrap_or(module_last);
                            let matched: Vec<_> = free
                                .iter()
                                .filter(|fid| {
                                    let stem_hit = file_stem(&fid.file) == module_stem;
                                    let dir_hit = fid
                                        .file
                                        .rsplit('/')
                                        .nth(1)
                                        .map(|d| d == module_last)
                                        .unwrap_or(false);
                                    stem_hit || dir_hit
                                })
                                .collect();
                            if !matched.is_empty() {
                                import_hit = true;
                                same_dir_zero_has_import_hit += 1;
                                if matched.len() == 1 {
                                    same_dir_zero_import_hit_singleton += 1;
                                } else {
                                    same_dir_zero_import_hit_multi += 1;
                                }
                            }
                        }
                    }
                    if !import_hit {
                        same_dir_zero_no_import += 1;
                        if same_dir_zero_no_import_examples.len() < 8 {
                            same_dir_zero_no_import_examples.push(format!(
                                "{}:{} calls `{}` ({} total candidates across {} dirs)",
                                caller_file,
                                site.line,
                                name,
                                free.len(),
                                free.iter().map(|f| dir_of(&f.file)).collect::<std::collections::BTreeSet<_>>().len()
                            ));
                        }
                    }
                }
                _ => {
                    same_dir_multi += 1;
                    if same_dir_multi_examples.len() < 8 {
                        same_dir_multi_examples.push(format!(
                            "{}:{} calls `{}` ({} candidates in own dir `{}`)",
                            caller_file,
                            site.line,
                            name,
                            same_dir.len(),
                            caller_dir
                        ));
                    }
                }
            }
        }
