use std::collections::BTreeMap;
use std::path::PathBuf;

use prism::call_graph::CallGraph;
use prism::navigation::NavigationIndex;
use prism::resolution::{DropReason, ResolutionConfidence, ResolutionKind};

fn dir_of(path: &str) -> &str {
    match path.rfind('/') {
        Some(i) => &path[..i],
        None => "",
    }
}

fn file_stem(path: &str) -> &str {
    let base = match path.rfind('/') {
        Some(i) => &path[i + 1..],
        None => path,
    };
    match base.rfind('.') {
        Some(i) => &base[..i],
        None => base,
    }
}

fn main() {
    let repo_path = std::env::args().nth(1).expect("repo path");
    let repo = std::sync::Arc::new(prism::repo_loader::load_repo(&PathBuf::from(&repo_path)).unwrap());
    let index = NavigationIndex::build(&repo);
    let cg: &CallGraph = &index.cpg.call_graph;

    let mut total_free_multi = 0usize;
    let mut same_dir_singleton = 0usize;
    let mut same_dir_singleton_shadowed = 0usize;
    let mut same_dir_multi = 0usize;
    let mut same_dir_zero_has_import_hit = 0usize;
    let mut same_dir_zero_import_hit_singleton = 0usize;
    let mut same_dir_zero_import_hit_singleton_shadowed = 0usize;
    let mut same_dir_zero_import_hit_multi = 0usize;
    let mut same_dir_zero_no_import = 0usize;
    let mut same_dir_zero_no_import_shadowed = 0usize;
    let mut same_dir_zero_no_import_examples: Vec<String> = Vec::new();
    let mut same_dir_multi_examples: Vec<String> = Vec::new();
    let mut same_dir_singleton_shadowed_examples: Vec<String> = Vec::new();

    let is_shadowed = |caller_file: &str, line: usize, name: &str| -> bool {
        let parsed = match repo.files.get(caller_file) {
            Some(p) => p,
            None => return false,
        };
        let func_node = match parsed.enclosing_function(line) {
            Some(f) => f,
            None => return false,
        };
        let params = parsed.function_parameter_names(&func_node);
        params.iter().any(|p| p == name)
    };

    for sites in cg.calls.values() {
        for site in sites {
            let out = cg.resolve_call_site_full(site);
            let is_free_multi = out.resolved.iter().any(|c| {
                c.kind == ResolutionKind::FreeMulti && c.confidence == ResolutionConfidence::NameOnly
            }) || out.drop == Some(DropReason::MultiOwnerCollision) && false;
            if !is_free_multi {
                continue;
            }
            // only count once per site (site-level), not per fanned-out callee
            total_free_multi += 1;

            let name = &site.callee_name;
            let caller_file = &site.caller.file;
            let caller_dir = dir_of(caller_file);

            let ids = match cg.functions.get(name) {
                Some(v) => v,
                None => continue,
            };
            let free: Vec<_> = ids
                .iter()
                .filter(|fid| !cg.method_owners.contains_key(*fid))
                .collect();

            let same_dir: Vec<_> = free.iter().filter(|f| dir_of(&f.file) == caller_dir).collect();

            match same_dir.len() {
                1 => {
                    same_dir_singleton += 1;
                    if is_shadowed(caller_file, site.line, name) {
                        same_dir_singleton_shadowed += 1;
                        if same_dir_singleton_shadowed_examples.len() < 8 {
                            same_dir_singleton_shadowed_examples.push(format!(
                                "{}:{} calls `{}` (param-shadowed, same-dir candidate would wrongly win)",
                                caller_file, site.line, name
                            ));
