                                module_path.rsplit('/').next().unwrap_or(module_path);
                            let module_stem =
                                module_last.rsplit('.').last().unwrap_or(module_last);
                            let matched: Vec<_> = free
                                .iter()
                                .filter(|fid| {
                                    let stem_hit = file_stem(&fid.file) == module_stem;
                                    let dir_hit = fid
                                        .file
                                        .rsplit('/')
                                        .nth(1)
                                        .map(|d| d == module_last)
                                        .unwrap_or(false);
                                    stem_hit || dir_hit
                                })
                                .collect();
                            if !matched.is_empty() {
                                import_hit = true;
                                same_dir_zero_has_import_hit += 1;
                                if matched.len() == 1 {
                                    same_dir_zero_import_hit_singleton += 1;
                                    if is_shadowed(caller_file, site.line, name) {
                                        same_dir_zero_import_hit_singleton_shadowed += 1;
                                    }
                                } else {
                                    same_dir_zero_import_hit_multi += 1;
                                }
                            }
                        }
                    }
                    if !import_hit {
                        same_dir_zero_no_import += 1;
                        if is_shadowed(caller_file, site.line, name) {
                            same_dir_zero_no_import_shadowed += 1;
                        }
                        if same_dir_zero_no_import_examples.len() < 8 {
                            same_dir_zero_no_import_examples.push(format!(
                                "{}:{} calls `{}` ({} total candidates across {} dirs)",
                                caller_file,
                                site.line,
                                name,
                                free.len(),
                                free.iter().map(|f| dir_of(&f.file)).collect::<std::collections::BTreeSet<_>>().len()
                            ));
                        }
                    }
                }
                _ => {
                    same_dir_multi += 1;
                    if same_dir_multi_examples.len() < 8 {
                        same_dir_multi_examples.push(format!(
                            "{}:{} calls `{}` ({} candidates in own dir `{}`)",
                            caller_file,
                            site.line,
                            name,
                            same_dir.len(),
                            caller_dir
                        ));
                    }
                }
            }
        }
    }

    println!("repo: {}", repo_path);
    println!("total_free_multi_sites: {}", total_free_multi);
    println!("same_dir_singleton (would become Exact under same-dir pref): {}", same_dir_singleton);
    println!("same_dir_multi (still ambiguous even with same-dir pref): {}", same_dir_multi);
    println!("same_dir_zero_no_import (no candidate in dir, no import binding): {}", same_dir_zero_no_import);
    println!("same_dir_zero_has_import_hit (import binding resolves to >=1 file): {}", same_dir_zero_has_import_hit);
    println!("  of which import_hit_singleton (would become Exact via import): {}", same_dir_zero_import_hit_singleton);
    println!("  of which import_hit_multi (import narrows but still >1): {}", same_dir_zero_import_hit_multi);

    println!("\nsame_dir_multi examples:");
    for e in &same_dir_multi_examples {
        println!("  {}", e);
    }
    println!("\nsame_dir_zero_no_import examples:");
    for e in &same_dir_zero_no_import_examples {
        println!("  {}", e);
    }

    let _ : BTreeMap<(), ()> = BTreeMap::new();
}

