                                caller_file, site.line, name
                            ));
                        }
                    }
                }
                0 => {
                    // no candidate in caller's own directory -- would same-dir
                    // preference even fire? check import-qualified narrowing
                    // instead: does caller's file import `name` from some module,
                    // and does that module resolve to a unique file?
                    let mut import_hit = false;
                    if let Some(file_imports) = cg.imports.get(caller_file) {
                        if let Some(module_path) = file_imports.get(name) {
                            let module_last =
                                module_path.rsplit('/').next().unwrap_or(module_path);
                            let module_stem =
                                module_last.rsplit('.').last().unwrap_or(module_last);
                            let matched: Vec<_> = free
                                .iter()
                                .filter(|fid| {
                                    let stem_hit = file_stem(&fid.file) == module_stem;
                                    let dir_hit = fid
                                        .file
                                        .rsplit('/')
                                        .nth(1)
                                        .map(|d| d == module_last)
                                        .unwrap_or(false);
                                    stem_hit || dir_hit
                                })
                                .collect();
                            if !matched.is_empty() {
                                import_hit = true;
                                same_dir_zero_has_import_hit += 1;
                                if matched.len() == 1 {
                                    same_dir_zero_import_hit_singleton += 1;
                                    if is_shadowed(caller_file, site.line, name) {
