    println!("total_free_multi_sites: {}", total_free_multi);
    println!("same_dir_singleton (would become Exact under same-dir pref): {}", same_dir_singleton);
    println!("  of which shadowed by local param (would be a WRONG Exact): {}", same_dir_singleton_shadowed);
    println!("same_dir_multi (still ambiguous even with same-dir pref): {}", same_dir_multi);
    println!("same_dir_zero_no_import (no candidate in dir, no import binding): {}", same_dir_zero_no_import);
    println!("  of which shadowed by local param: {}", same_dir_zero_no_import_shadowed);
    println!("same_dir_zero_has_import_hit (import binding resolves to >=1 file): {}", same_dir_zero_has_import_hit);
    println!("  of which import_hit_singleton (would become Exact via import): {}", same_dir_zero_import_hit_singleton);
    println!("    of which shadowed by local param (would be a WRONG Exact): {}", same_dir_zero_import_hit_singleton_shadowed);
    println!("  of which import_hit_multi (import narrows but still >1): {}", same_dir_zero_import_hit_multi);

    println!("\nshadowed same_dir_singleton examples:");
    for e in &same_dir_singleton_shadowed_examples {
        println!("  {}", e);
    }

    println!("\nsame_dir_multi examples:");
